function rtBroadcast(event, payload){
  if(_rtChannel) _rtChannel.send({type:"broadcast", event, payload}).catch(()=>{});
}

// ── Funciones de sincronización ──────────────────────────
async function sbGuardarProducto(prod) {
  try {
    const db = await getSupabase();
    // La tabla inventario usa bigint para id.
    // Solo se envía id si es numérico válido; si es string (ID local), insert sin id.
    const numId = Number(prod.id);
    const idEsNumerico = !isNaN(numId) && numId > 0 && Number.isFinite(numId);
    const payload = {
      codigo:      prod.codigo,
      marca_id:    prod.marcaId,
      marca_nombre:prod.marcaNombre,
      nombre:      prod.nombre,
      categoria:   prod.categoria||"GENERAL",
      descripcion: prod.descripcion||"",
      subcat:      prod.subcat||"",
      precio:      prod.precio,
      stock:       prod.stock,
      stock_inicial:prod.stockInicial||prod.stock,
      fecha:       prod.fecha||hoy(),
    };
    if(idEsNumerico) payload.id = numId;
    const { data, error } = await db.from("inventario")
      .upsert(payload, { onConflict: idEsNumerico ? "id" : "codigo" })
      .select("id").maybeSingle();
    if(error) throw error;
    // Devuelve el id asignado por Supabase para actualizar estado local
    return data?.id ?? prod.id;
  } catch(e) {
    console.error("[Supabase] inventario save FAILED:", e.message, "prod.id:", prod.id);
    return null;
  }
}

async function sbGuardarProductosBatch(prods) {
  if(!prods.length) return true;
  try {
    const db = await getSupabase();
    const payload = prods.map(prod => ({
      codigo:       prod.codigo,
      marca_id:     prod.marcaId,
      marca_nombre: prod.marcaNombre,
      nombre:       prod.nombre,
      categoria:    prod.categoria||"GENERAL",
      descripcion:  prod.descripcion||"",
      subcat:       prod.subcat||"",
      precio:       prod.precio,
      stock:        prod.stock,
      stock_inicial:prod.stockInicial||prod.stock,
      fecha:        prod.fecha||hoy(),
    }));
    const { error } = await db.from("inventario").upsert(payload, { onConflict: "codigo" });
    if(error) throw error;
    return true;
  } catch(e) {
    console.error("[Supabase] batch save FAILED:", e.message, "n=", prods.length);
    // Fallback: intentar uno por uno
    let allOk = true;
    for(const p of prods){ const ok = await sbGuardarProducto(p); if(!ok) allOk=false; }
    return allOk;
  }
}

// Verifica contra la NUBE (no estado local) qué códigos existen realmente.
// Devuelve un Set de códigos presentes (en mayúsculas) o null si no se pudo consultar.
async function sbExistenCodigos(codigos){
  if(!codigos || !codigos.length) return new Set();
  try{
    const db = await getSupabase();
    const present = new Set();
    // Consultar en lotes de 200 para no exceder el largo de URL
    for(let i=0;i<codigos.length;i+=200){
      const lote = codigos.slice(i,i+200);
      const { data, error } = await db.from("inventario").select("codigo").in("codigo", lote);
      if(error) throw error;
      (data||[]).forEach(r=>present.add((r.codigo||"").toUpperCase().trim()));
    }
    return present;
  }catch(e){ console.warn("[verif] sbExistenCodigos:", e.message); return null; }
}

