// PostgREST corta en 1000 filas por request. Este helper trae TODO paginando
// con .range() hasta que una página devuelve menos de 1000 (fin de la tabla).
// Sin esto, inventarios/ventas con >1000 filas se cargaban truncados.
async function sbSelectAll(db, tabla, columns="*") {
  const PAGE = 1000;
  let from = 0, out = [];
  for(;;){
    const { data, error } = await db.from(tabla).select(columns).range(from, from+PAGE-1);
    if(error) throw error;
    out = out.concat(data||[]);
    if(!data || data.length < PAGE) break;
    from += PAGE;
  }
  return out;
}

async function sbCargarTodo() {
  try {
    const db = await getSupabase();
    const [inv, ventas, items, cierres] = await Promise.all([
      sbSelectAll(db, "inventario"),
      sbSelectAll(db, "ventas"),
      sbSelectAll(db, "venta_items"),
      sbSelectAll(db, "cierres"),
    ]);

    // Reconstruir ventas con sus items
    const ventasCompletas = (ventas||[]).map(v => ({
      id: v.id, fecha: v.fecha, hora: v.hora, mk: v.mk,
      mes: v.mes, anio: v.anio, total: v.total, subtotal: v.subtotal,
      descPct: v.desc_pct, metodoPago: v.metodo_pago,
      vendedor: v.vendedor, etiquetaImg: v.etiqueta_img,
      clienteNombre: v.cliente_nombre||"", clienteTelefono: v.cliente_telefono||"",
      anulada: v.anulada || false,
      items: (items||[]).filter(i=>i.venta_id===v.id).map(i=>({
        prodId: i.prod_id, codigo: i.codigo, nombre: i.nombre,
        marcaId: i.marca_id, marcaNombre: i.marca_nombre,
        cantidad: i.cantidad, precioUnit: i.precio_unit, subtotal: i.subtotal
      }))
    }));

    // Reconstruir inventario
    const invCompleto = (inv||[]).map(p => ({
      id: p.id, codigo: p.codigo, marcaId: p.marca_id,
      marcaNombre: p.marca_nombre, nombre: p.nombre,
      categoria: p.categoria, precio: p.precio,
      descripcion: p.descripcion||"", subcat: p.subcat||"",
      stock: p.stock, stockInicial: p.stock_inicial, fecha: p.fecha
    }));

    // Reconstruir cierres
    const cierresObj = {};
    (cierres||[]).forEach(c => { cierresObj[c.id] = { cerrado: c.cerrado, fecha: c.fecha, mk: c.mk }; });

    return { inv: invCompleto, ventas: ventasCompletas, cierres: cierresObj };
  } catch(e) {
    console.warn("Supabase load error:", e.message);
    return null;
  }
}

// Recarga SOLO el inventario desde Supabase (fuente de verdad).
// Se usa cuando se elimina una carga en otro dispositivo: en vez de depender
// de recibir N eventos DELETE individuales (que el realtime descarta en ráfaga),
// se vuelve a leer la lista completa y queda 100% sincronizada.
async function sbCargarInventario() {
  try {
    const db = await getSupabase();
    const data = await sbSelectAll(db, "inventario");
    return (data || []).map(p => ({
      id: p.id, codigo: p.codigo, marcaId: p.marca_id,
      marcaNombre: p.marca_nombre, nombre: p.nombre,
      categoria: p.categoria, precio: p.precio,
      descripcion: p.descripcion||"", subcat: p.subcat||"",
      stock: p.stock, stockInicial: p.stock_inicial, fecha: p.fecha
    }));
  } catch(e) { console.warn("Supabase recargar inventario:", e.message); return null; }
}

// ── Auditoría forense en la nube (sync en tiempo real entre dispositivos) ──
async function sbGuardarAuditLog(evento) {
  try {
    const db = await getSupabase();
    const {id, ts, fecha, hora, tipo, usuario, nombre, rol, ...detalle} = evento;
    const { error } = await db.from("audit_log").upsert({id, ts, fecha, hora, tipo, usuario, nombre, rol, detalle});
    if (error) throw error;
    return true;
  } catch(e) { console.warn("Supabase save audit_log:", e.message); return false; }
}

async function sbCargarAuditLog() {
  try {
    const db = await getSupabase();
    const { data, error } = await db.from("audit_log").select("*").order("ts",{ascending:false}).limit(1000);
    if (error) throw error;
    return (data||[]).map(a=>({
      id:a.id, ts:a.ts, fecha:a.fecha, hora:a.hora,
      tipo:a.tipo, usuario:a.usuario, nombre:a.nombre, rol:a.rol,
      ...(a.detalle||{}),
    }));
  } catch(e) { console.warn("Supabase load audit_log:", e.message); return null; }
}

// ════════════════════════════════════════════════════════════
// OUTBOX — cola de respaldo para sincronización con Supabase.
// Toda escritura que falle (sin internet, error del servidor, etc.)
// se guarda aquí y se reintenta automáticamente al reconectar o de
// forma periódica, para que ningún dato se pierda aunque la nube
// no esté disponible en el momento de guardar.
// ════════════════════════════════════════════════════════════
const TH_OUTBOX_KEY = "th_sync_outbox";

function getOutbox(){
  try{ return JSON.parse(localStorage.getItem(TH_OUTBOX_KEY)||"[]"); }catch{ return []; }
}
function setOutbox(lista){
  try{ localStorage.setItem(TH_OUTBOX_KEY, JSON.stringify(lista)); }catch{}
  try{ window.dispatchEvent(new CustomEvent("th-outbox-changed",{detail:{count:lista.length}})); }catch{}
}
function pushToOutbox(tipo, payload){
  const op = { id:`${Date.now()}-${Math.random().toString(36).slice(2,8)}`, tipo, payload, ts:Date.now(), intentos:0 };
  setOutbox([...getOutbox(), op]);
  return op.id;
}
function removeFromOutbox(id){
  setOutbox(getOutbox().filter(o=>o.id!==id));
}

// Ejecuta la operación sb* correspondiente a un ítem de la cola.
// Devuelve true si Supabase confirmó la escritura (sale de la cola).
async function ejecutarOpOutbox(op){
  switch(op.tipo){
    case "producto":    return !!(await sbGuardarProducto(op.payload));
    case "stock":         return op.payload.stock_inicial!=null
                            ? await sbActualizarProductoPatch(op.payload.prodId, {stock:Math.max(0,op.payload.stock), stock_inicial:op.payload.stock_inicial})
                            : await sbActualizarStock(op.payload.prodId, op.payload.stock);
    case "producto_patch":return await sbActualizarProductoPatch(op.payload.prodId, op.payload);
    case "venta":       return await sbGuardarVenta(op.payload);
    case "anularVenta": return await sbAnularVenta(op.payload.id);
    case "cierre":      return await sbGuardarCierre(op.payload.key, op.payload.data);
    case "retiro":      return await sbGuardarRetiro(op.payload);
    case "carga":       return await sbGuardarCarga(op.payload);
    case "auditoria":   return await sbGuardarAuditoria(op.payload);
    case "auditLog":    return await sbGuardarAuditLog(op.payload);
    case "usuarios":    return await sbGuardarUsuarios(op.payload);
    case "marcas":      return await sbGuardarMarcas(op.payload);
    case "eliminarProductoCodigo": return await sbEliminarProductoPorCodigo(op.payload.codigo);
    case "eliminarProductosCodigos": return await sbEliminarProductosPorCodigos(op.payload.codigos);
    case "eliminarCarga":          return await sbEliminarCarga(op.payload.cargaId);
    default: return true; // tipo desconocido — no bloquear la cola
  }
}

let _procesandoOutbox = false;
// Recorre la cola en orden y descarta los ítems que Supabase confirme.
// Los que sigan fallando quedan en la cola para el próximo intento.
async function procesarOutbox(){
  if(_procesandoOutbox) return;
  if(typeof navigator!=="undefined" && navigator.onLine===false) return;
  if(getOutbox().length===0) return;
  _procesandoOutbox = true;
  try{
    for(const op of getOutbox()){
      let ok=false;
      try{ ok = await ejecutarOpOutbox(op); }catch{ ok=false; }
      if(ok){
        removeFromOutbox(op.id);
      }else{
        const actual = getOutbox();
        const idx = actual.findIndex(o=>o.id===op.id);
        if(idx>=0){
          actual[idx].intentos = (actual[idx].intentos||0)+1;
          actual[idx].ultimoIntento = Date.now();
          setOutbox(actual);
        }
      }
    }
  } finally {
    _procesandoOutbox = false;
  }
}

// Difunde la operación a las otras sesiones por broadcast (ruta rápida ~1 RTT,
// sin esperar el WAL polling de postgres_changes). postgres_changes llega después
// y corrige cualquier drift — los listeners deduplican por id.
function rtBroadcastForOp(tipo, payload){
  try{
    switch(tipo){
      case "stock": {
        const p = {id: payload.prodId, stock: payload.stock};
        if(payload.stock_inicial!=null) p.stockInicial = payload.stock_inicial;
        rtBroadcast("inv_update", {p});
        break;
      }
      case "producto_patch": {
        const p = {id: payload.prodId};
        if(payload.stock!=null)         p.stock        = payload.stock;
        if(payload.stock_inicial!=null) p.stockInicial = payload.stock_inicial;
        if(payload.nombre)              p.nombre       = payload.nombre;
        if(payload.precio!=null)        p.precio       = payload.precio;
        if(payload.categoria)           p.categoria    = payload.categoria;
        if(payload.descripcion)         p.descripcion  = payload.descripcion;
        if(payload.subcat)              p.subcat       = payload.subcat;
        if(payload.codigo)              p.codigo       = payload.codigo;
        rtBroadcast("inv_update", {p});
        break;
      }
      case "venta": {
        // sin imagen base64: el broadcast tiene límite de tamaño de payload
        const {etiquetaImg, ...v} = payload;
        rtBroadcast("venta_nueva", {v});
        break;
      }
      case "anularVenta": rtBroadcast("venta_anulada",{id: payload.id}); break;
      case "retiro":      rtBroadcast("retiro_nuevo", {r: payload}); break;
    }
  }catch{ /* broadcast es best-effort; postgres_changes respalda */ }
}

// Intenta guardar en Supabase de inmediato; si no hay red o falla,
// encola la operación para reintento automático. Los datos ya están
// seguros en localStorage (estado React) independientemente del resultado.
async function syncConRespaldo(tipo, payload, fnDirecto){
  rtBroadcastForOp(tipo, payload);
  try{
    if(typeof navigator!=="undefined" && navigator.onLine===false){
      pushToOutbox(tipo, payload);
      return false;
    }
    const ok = await fnDirecto();
    if(!ok){ pushToOutbox(tipo, payload); }
    return ok;
  }catch(e){
    pushToOutbox(tipo, payload);
    return false;
  }
}

// ── Realtime sync — escucha cambios en Supabase y actualiza estado local ────
// Activa canales en: ventas (INSERT/UPDATE) + inventario (INSERT/UPDATE)
// Deduplicación: si la fila ya existe (optimistic update local), no se agrega.
function useRealtimeSync(setVentas, setInv, setRetiros, setFactoryResetRecibido, onResync) {
  useEffect(() => {
    let channel = null;
    let mounted = true;
    let wasConnected = false; // para detectar re-suscripción tras caída

    getSupabase().then(db => {
      if (!mounted) return;
      channel = db.channel("toscana-realtime-v3")
        // ── Venta nueva ────────────────────────────────────────────────────
        .on("postgres_changes", { event: "INSERT", schema: "public", table: "ventas" }, async payload => {
          const v = payload.new;
          try {
            const { data: rawItems } = await db.from("venta_items").select("*").eq("venta_id", v.id);
            const venta = {
              id: v.id, fecha: v.fecha, hora: v.hora, mk: v.mk,
              mes: v.mes, anio: v.anio, total: v.total, subtotal: v.subtotal,
              descPct: v.desc_pct, metodoPago: v.metodo_pago,
              vendedor: v.vendedor, etiquetaImg: v.etiqueta_img,
              anulada: v.anulada || false,
              items: (rawItems || []).map(i => ({
                prodId: i.prod_id, codigo: i.codigo, nombre: i.nombre,
                marcaId: i.marca_id, marcaNombre: i.marca_nombre,
                cantidad: i.cantidad, precioUnit: i.precio_unit, subtotal: i.subtotal
              }))
            };
            if (mounted) setVentas(prev =>
              prev.some(x => x.id === venta.id) ? prev : [...prev, venta]
            );
          } catch(e) { console.warn("[RT] venta insert:", e.message); }
        })
        // ── Venta actualizada (anulada, etc.) ───────────────────────────
        .on("postgres_changes", { event: "UPDATE", schema: "public", table: "ventas" }, payload => {
          const v = payload.new;
          if (mounted) setVentas(prev => prev.map(x => x.id === v.id ? {
            ...x,
            anulada: v.anulada || false,
            total: v.total,
            subtotal: v.subtotal,
            metodoPago: v.metodo_pago,
          } : x));
        })
        // ── Producto nuevo en inventario ────────────────────────────────
        .on("postgres_changes", { event: "INSERT", schema: "public", table: "inventario" }, payload => {
          const p = payload.new;
          const prod = {
            id: p.id, codigo: p.codigo, marcaId: p.marca_id,
            marcaNombre: p.marca_nombre, nombre: p.nombre,
            categoria: p.categoria, precio: p.precio,
            stock: p.stock, stockInicial: p.stock_inicial, fecha: p.fecha
          };
          if (mounted) setInv(prev =>
            prev.some(x => x.id === prod.id) ? prev : [...prev, prod]
          );
        })
        // ── Stock / precio actualizado ───────────────────────────────────
        .on("postgres_changes", { event: "UPDATE", schema: "public", table: "inventario" }, payload => {
          const p = payload.new;
          if (mounted) setInv(prev => prev.map(i => i.id === p.id ? {
            ...i, codigo: p.codigo||i.codigo, stock: p.stock, nombre: p.nombre, precio: p.precio, categoria: p.categoria, descripcion: p.descripcion||i.descripcion
          } : i));
        })
        // ── Producto eliminado del inventario (rollback de carga) ──────────
        .on("postgres_changes", { event: "DELETE", schema: "public", table: "inventario" }, payload => {
          const id = payload.old?.id;
          if(mounted && id) setInv(prev => prev.filter(i => i.id !== id));
        })
        // ── Retiro registrado en otro dispositivo ───────────────────────
        .on("postgres_changes", { event: "INSERT", schema: "public", table: "retiros" }, payload => {
          const r = payload.new;
          const retiro = {
            id: r.id, fecha: r.fecha, hora: r.hora,
            prodId: r.prod_id, codigo: r.codigo, nombre: r.nombre,
            marcaId: r.marca_id, marcaNombre: r.marca_nombre,
            cantidad: r.cantidad, destinatario: r.destinatario, motivo: r.motivo||""
          };
          if (mounted && setRetiros) setRetiros(prev =>
            prev.some(x => x.id === retiro.id) ? prev : [...prev, retiro]
          );
        })
        // ── Broadcast: venta nueva (ruta rápida ~80ms, sin extra DB query) ──
        .on("broadcast", {event:"venta_nueva"}, ({payload}) => {
          const v = payload?.v;
          if(mounted && v?.id) setVentas(prev => prev.some(x=>x.id===v.id) ? prev : [...prev, v]);
        })
        // ── Broadcast: stock actualizado (ruta rápida para caja concurrente) ──
        .on("broadcast", {event:"inv_update"}, ({payload}) => {
          const p = payload?.p;
          if(mounted && p?.id) setInv(prev => prev.map(i => i.id===p.id ? {...i,...p} : i));
        })
        // ── Broadcast: retiro nuevo (ruta rápida) ──
        .on("broadcast", {event:"retiro_nuevo"}, ({payload}) => {
          const r = payload?.r;
          if(mounted && r?.id && setRetiros) setRetiros(prev => prev.some(x=>x.id===r.id) ? prev : [...prev, r]);
        })
        // ── Broadcast: venta anulada (ruta rápida) ──
        .on("broadcast", {event:"venta_anulada"}, ({payload}) => {
          const id = payload?.id;
          if(mounted && id) setVentas(prev => prev.map(x => x.id===id ? {...x, anulada:true} : x));
        })
        // ── Broadcast: factory reset → limpiar y recargar esta sesión ────────
        .on("broadcast", {event:"factory_reset"}, () => {
          if(!mounted) return;
          ["th_inv","th_ventas","th_cierres","th_cargas","th_sync_log","th_pos_draft",
           "th_liq_cfg","th_cajas_v1","th_gc_v1"].forEach(k=>localStorage.removeItem(k));
          Object.keys(localStorage).forEach(k=>{
            if(k.startsWith("th_fac_")||k.startsWith("th_liq_")||k.startsWith("th_gc_"))
              localStorage.removeItem(k);
          });
          setFactoryResetRecibido(true);
          setTimeout(()=>window.location.reload(), 3000);
        })
        .subscribe(status => {
          if (status === "SUBSCRIBED"){
            console.log("[Toscana Realtime] ✓ conectado");
            _rtChannel = channel; // exponer globalmente para rtBroadcast
            // Re-suscripción tras caída → refetch completo: los eventos perdidos
            // durante la desconexión no se re-emiten, hay que recargar.
            if (wasConnected && onResync) onResync();
            wasConnected = true;
          }
          if (status === "CHANNEL_ERROR") console.warn("[Toscana Realtime] error de canal — verifique Realtime en Supabase dashboard");
        });
    }).catch(e => console.warn("[Toscana Realtime] init:", e.message));

    return () => {
      mounted = false;
      _rtChannel = null;
      if (channel) {
        getSupabase().then(db => db.removeChannel(channel)).catch(() => {});
      }
    };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
}

// ── Detector de reloj desviado ───────────────────────────────────────
// La app estampa fecha/hora de las ventas con el reloj LOCAL del equipo.
// Compara ese "reloj de pared" contra la hora real de Bolivia (epoch del
// header Date del servidor, same-origin → siempre legible). Detecta tanto
// reloj corrido (caja +37 min) como zona horaria mal configurada (+6 h).
function useClockDrift(){
  var _hCD = useState(0); var driftMin = _hCD[0]; var setDriftMin = _hCD[1];
  useEffect(()=>{
    let mounted = true;
    // Convierte un instante a "minutos de pared" en una zona horaria dada
    const wallMin = (dt, tz) => {
      const parts = new Intl.DateTimeFormat("en-CA",{
        ...(tz?{timeZone:tz}:{}),
        year:"numeric",month:"2-digit",day:"2-digit",
        hour:"2-digit",minute:"2-digit",hour12:false,
      }).formatToParts(dt);
      const g = t => +parts.find(x=>x.type===t).value;
      return Date.UTC(g("year"),g("month")-1,g("day"),g("hour")%24,g("minute"))/60000;
    };
    async function medir(){
      try{
        const r = await fetch(`/version.json?_=${Date.now()}`, {cache:"no-store"});
        const d = r.headers.get("date");
        if(!d || !mounted) return;
        const serverEpoch = new Date(d).getTime();
        if(!serverEpoch) return;
        // Lo que estampa este equipo vs lo que debería estampar (hora Bolivia real)
        const drift = wallMin(new Date(), null) - wallMin(new Date(serverEpoch), "America/La_Paz");
        if(mounted) setDriftMin(Math.round(drift));
      }catch{ /* sin red → no medir */ }
    }
    medir();
    const iv = setInterval(medir, 10*60*1000);
    return ()=>{ mounted=false; clearInterval(iv); };
  },[]);
  return driftMin;
}

// Banner rojo fijo — visible para TODOS los roles mientras el reloj esté mal
function ClockDriftBanner({driftMin}){
  if(Math.abs(driftMin) < 5) return null;
  const abs = Math.abs(driftMin);
  const txt = abs >= 90
    ? `${Math.round(abs/60)} hora${Math.round(abs/60)===1?"":"s"}`
    : `${abs} minuto${abs===1?"":"s"}`;
  return (
    <div style={{
      position:"fixed", top:0, left:0, right:0, zIndex:99998,
      background:"#C62828", color:"#fff",
      padding:"9px 16px", textAlign:"center",
      fontFamily:FONT_UI, fontSize:13, fontWeight:600, lineHeight:1.4,
      boxShadow:"0 2px 8px rgba(0,0,0,0.25)",
    }}>
      ⚠️ El reloj de este equipo está {driftMin>0?"adelantado":"atrasado"} {txt} —
      las ventas se registran con hora equivocada. Corregir en Ajustes → Fecha y hora
      (activar "automático") o avisar al administrador.
    </div>
  );
}

// Mide latencia RTT al servidor de Supabase Realtime mediante broadcast self:true
function usePingLatency(){
  var _hPing = useState(null); var latencyMs = _hPing[0]; var setLatencyMs = _hPing[1];
  useEffect(()=>{
    let ch = null, iv = null, mounted = true;
    getSupabase().then(db=>{
      ch = db.channel("toscana-ping-v1", {config:{broadcast:{self:true}}});
      ch.on("broadcast", {event:"ping"}, ({payload})=>{
        if(mounted && payload?.ts) setLatencyMs(Math.round(Date.now()-payload.ts));
      }).subscribe(status=>{
        if(status==="SUBSCRIBED"){
          const doPing = ()=>{ if(mounted) ch.send({type:"broadcast",event:"ping",payload:{ts:Date.now()}}).catch(()=>{}); };
          doPing();
          iv = setInterval(doPing, 15000);
        }
      });
    }).catch(()=>{});
    return ()=>{
      mounted=false;
      if(iv) clearInterval(iv);
      if(ch) getSupabase().then(db=>db.removeChannel(ch)).catch(()=>{});
    };
  },[]);
  return latencyMs;
}

// Hook de estado de conexión Supabase
function useSupabaseStatus() {
  var _hN100 = useState("connecting"); var status = _hN100[0]; var setStatus = _hN100[1];; // connecting | ok | error
  useEffect(() => {
    getSupabase()
      .then(db => db.from("inventario").select("id").limit(1))
      .then(() => setStatus("ok"))
      .catch(() => setStatus("error"));
  }, []);
  return status;
}


// ════════════════════════════════════════════════════════════
// MOTOR DE CÓDIGOS DE BARRAS — JsBarcode + ZXing Scanner
// ════════════════════════════════════════════════════════════

// Carga JsBarcode desde CDN (genera códigos CODE128)
let _JsBarcodeLoaded = false;
function loadJsBarcode() {
  return new Promise(res => {
    if (window.JsBarcode || _JsBarcodeLoaded) { res(true); return; }
    const s = document.createElement("script");
    s.src = "https://cdnjs.cloudflare.com/ajax/libs/jsbarcode/3.11.5/JsBarcode.all.min.js";
    s.onload = () => { _JsBarcodeLoaded = true; res(true); };
    s.onerror = () => res(false);
    document.head.appendChild(s);
  });
}


// Carga ZXing para leer códigos desde imagen
let _ZXingLoaded = false;
let _ZXingLib = null;
function loadZXing() {
  return new Promise(res => {
    if (_ZXingLib) { res(_ZXingLib); return; }
    const s = document.createElement("script");
    s.src = "https://unpkg.com/@zxing/library@0.19.1/umd/index.min.js";
    s.onload = () => { _ZXingLib = window.ZXing; res(window.ZXing); };
    s.onerror = () => res(null);
    document.head.appendChild(s);
  });
}

// (html5-qrcode removed — scanner uses native getUserMedia + ZXing instead)

// Lee código de barras/QR desde un archivo de imagen
async function leerCodigoDeImagen(file) {
  try {
    const ZXing = await loadZXing();
    if (!ZXing) return null;
    const img = new Image();
    const url = URL.createObjectURL(file);
    await new Promise((res, rej) => { img.onload = res; img.onerror = rej; img.src = url; });
    const canvas = document.createElement("canvas");
    canvas.width = img.width; canvas.height = img.height;
    canvas.getContext("2d").drawImage(img, 0, 0);
    URL.revokeObjectURL(url);
    const hints = new Map();
    const formats = [
      ZXing.BarcodeFormat.CODE_128, ZXing.BarcodeFormat.CODE_39,
      ZXing.BarcodeFormat.EAN_13,   ZXing.BarcodeFormat.EAN_8,
      ZXing.BarcodeFormat.QR_CODE,  ZXing.BarcodeFormat.DATA_MATRIX,
      ZXing.BarcodeFormat.ITF,      ZXing.BarcodeFormat.UPC_A,
    ];
    hints.set(ZXing.DecodeHintType.POSSIBLE_FORMATS, formats);
    hints.set(ZXing.DecodeHintType.TRY_HARDER, true);
    const reader = new ZXing.MultiFormatReader();
    reader.setHints(hints);
    const luminance = new ZXing.HTMLCanvasElementLuminanceSource(canvas);
    const binaryBitmap = new ZXing.BinaryBitmap(new ZXing.HybridBinarizer(luminance));
    const result = reader.decode(binaryBitmap);
    return result?.text || null;
  } catch (e) {
    // Intento con rotaciones si falla el primero
    return null;
  }
}

function limpiarCod(c){ return (c||"").toUpperCase().replace(/[^A-Z0-9]/g,""); }

// Genera código de barras CODE128 como SVG (string)
async function generarSVGBarcode(codigo) {
  try {
    const ok = await loadJsBarcode();
    if (!ok || !window.JsBarcode) return null;
    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    window.JsBarcode(svg, codigo, {
      format: "CODE128",
      width: 2, height: 70,
      displayValue: false,
      margin: 0,
      background: "#ffffff",
      lineColor: "#1A2E1A",
    });
    return `<div style="display:flex;justify-content:center">${svg.outerHTML}</div>`;
  } catch(e) {
    return null;
  }
}

// Componente: muestra código de barras CODE128 inline
function BarcodeDisplay({ codigo, small }) {
  const svgRef = useRef(null);

  useEffect(() => {
    if (!codigo || !svgRef.current) return;
    loadJsBarcode().then(ok => {
      if (!ok || !window.JsBarcode || !svgRef.current) return;
      try {
        window.JsBarcode(svgRef.current, codigo, {
          format: "CODE128",
          width: small ? 1.4 : 2,
          height: small ? 50 : 70,
          displayValue: false,
          margin: 4,
          background: "#ffffff",
          lineColor: "#1A2E1A",
        });
      } catch(e) {}
    });
  }, [codigo, small]);

  return (
    <div style={{display:"flex",flexDirection:"column",alignItems:"center",gap:6}}>
      <div style={{
        width:small?140:200, height:small?60:84,
        background:"#fff", borderRadius:8, overflow:"hidden",
        display:"flex",alignItems:"center",justifyContent:"center",
      }}>
        {codigo ? <svg ref={svgRef}/> : <span style={{fontSize:11,color:"#aaa"}}>—</span>}
      </div>
      <div style={{fontFamily:"monospace",fontSize:10,color:"#5C8A5C",
        letterSpacing:1,textAlign:"center",maxWidth:small?140:200,
        wordBreak:"break-all"}}>{codigo}</div>
    </div>
  );
}

// Extrae el color del campo descripcion ("TALLA: X · COLOR: Y")
function extraerColor(desc){ const m=(desc||"").match(/COLOR:\s*([^·\n]+)/i); return m?m[1].trim():""; }
function extraerTalla(desc){ const m=(desc||"").match(/TALLA:\s*([^·\n]+)/i); return m?m[1].trim():""; }

// Construye la línea completa para etiqueta e inventario: NOMBRE TALLA X COLOR Y
// Igual en ambos lados — si el nombre ya incluye talla/color no los duplica
function lineaEtiqueta(nombre, descripcion){
  const nom = (nombre||"").toUpperCase().trim();
  const talla = extraerTalla(descripcion);
  const color = extraerColor(descripcion);
  const partes = [nom];
  if(talla && !nom.includes(talla.toUpperCase())) partes.push("TALLA "+talla.toUpperCase());
  if(color && !nom.includes(color.toUpperCase())) partes.push("COLOR "+color.toUpperCase());
  return partes.join(" ");
}

// ── Descuento manual real de una venta ─────────────────────────────
// Desde el 23-jun-2026 la comisión de tarjeta (1.8%) NO se cobra al cliente:
// va solo a la liquidación de la marca (calcLiqMarca → descTJ). descPct guarda
// únicamente el descuento manual del vendedor.
// Compat: ventas con tarjeta ANTERIORES al 23-jun sí llevaban el 1.8 incluido
// en descPct (el modelo viejo lo descontaba al cliente) → solo a esas se les
// resta para no alterar notas/liquidaciones ya emitidas.
const TARJETA_DESC_CLIENTE_HASTA = "2026-06-23";
function getManualDescPct(v){
  const legacy = v.metodoPago==="tarjeta" && (v.fecha||"") < TARJETA_DESC_CLIENTE_HASTA;
  return Math.max(0, (v.descPct||0) - (legacy ? 1.8 : 0));
}

// Retorna el total real de una venta para display: precio lleno de los items
// menos solo el descuento manual (nunca la comisión bancaria de tarjeta).
function getDisplayTotal(v){
  if(!v) return 0;
  const items=(v.items||[]);
  if(!items.length) return v.total||0;
  const itemsSum=items.reduce((s,i)=>s+(i.precioUnit||0)*(i.cantidad||1),0);
  if(!itemsSum) return v.total||0;
  const manualDescPct=getManualDescPct(v);
  return manualDescPct>0 ? +((itemsSum*(1-manualDescPct/100)).toFixed(2)) : itemsSum;
}

// Abrevia nombres largos de productos para que entren en la etiqueta
function abreviarNombre(nombre, maxLen = 90) {
  if (!nombre) return "";
  let n = nombre.trim();
  if (n.length <= maxLen) return n;
  const abreviaciones = {
    "MANGA LARGA":"M.LARGA", "MANGA CORTA":"M.CORTA", "SIN MANGA":"S/MANGA",
    "PANTALON":"PANT.", "PANTALÓN":"PANT.", "CHAQUETA":"CHAQ.", "CHAMARRA":"CHAM.",
    "VESTIDO":"VEST.", "CAMISA":"CAM.", "CHALECO":"CHAL.", "ASIMETRICO":"ASIM.",
    "ASIMÉTRICO":"ASIM.", "ESTAMPADO":"EST.", "BORDADO":"BORD.", "ESTRELLA":"ESTR.",
    "CUELLO":"CLLO.", "BOTONES":"BOT.", "BOLSILLOS":"BOLS.", "TRANSPARENTE":"TRANSP.",
    "DEPORTIVO":"DEP.", "DEPORTIVA":"DEP.",
  };
  for (const [full, short] of Object.entries(abreviaciones)) {
    n = n.replace(new RegExp(full, "g"), short);
  }
  if (n.length <= maxLen) return n;
  return n.slice(0, maxLen - 1).trim() + "…";
}

// Repite cada item según su stock, para imprimir una etiqueta por unidad física
// ── Unidades REALMENTE vendidas por código (verdad = registro de ventas) ──
// "Vendidas" SIEMPRE sale de ventas[], NUNCA de (stockInicial − stock):
// las bajas, reposiciones y reimportaciones cambian el stock sin ser ventas,
// y contaminarían el conteo. Esta es la única fuente de verdad de ventas.
function mapVendidasPorCodigo(ventas){
  const map = {};
  (ventas||[]).forEach(v=>{
    if(v.anulada) return;
    (v.items||[]).forEach(it=>{
      const k = (it.codigo||"").toUpperCase();
      if(k) map[k] = (map[k]||0) + (Number(it.cantidad)||0);
    });
  });
  return map;
}

// Id local único y monotónico. Evita colisiones del viejo Date.now()*1000+random
// cuando se crean muchos productos en el mismo milisegundo (import masivo).
let _localIdSeq = 0;
function nextLocalId(){ return Date.now()*1000 + (_localIdSeq++ % 1000); }

function expandirPorStock(items) {
  const out = [];
  for (const it of items) {
    const n = Math.max(0, Number(it.stock) || 0);
    for (let i = 0; i < n; i++) out.push(it);
  }
  return out;
}

