// ── Impresión con selección de cantidad ──────────────────────────────────────
// Cuando el producto tiene más de 1 unidad, pregunta cuántas etiquetas imprimir.
function imprimirConCantidad(prod, marcaNombre){
  const stock = Math.max(1, Number(prod.stock) || 1);
  const item = {...prod, marcaNombre: marcaNombre||prod.marcaNombre||""};
  if(stock <= 1){
    imprimirEtiquetasLote([{...item, stock:1}]);
    return;
  }
  const input = window.prompt(
    `¿Cuántas etiquetas de "${prod.nombre||prod.codigo}" querés imprimir?\n(Unidades en stock: ${stock})`,
    String(stock)
  );
  if(input === null) return;
  const cant = Math.max(1, Math.min(parseInt(input)||1, 9999));
  imprimirEtiquetasLote(expandirPorStock([{...item, stock:cant}]));
}

// ── Impresión de etiquetas en lote (un solo popup para todo el cargamento) ──
function imprimirEtiquetasLote(items) {
  if (!items || items.length === 0) return;
  const win = window.open("", "_blank", "width=900,height=700");
  if (!win) { alert("Activá las ventanas emergentes para imprimir"); return; }

  // Orden correlativo por código (ej: COM-001, COM-002, COM-003…) para que
  // las etiquetas impresas salgan en secuencia, sin importar el orden de
  // la lista en pantalla. "numeric:true" ordena los números dentro del
  // código de forma natural (1,2,…,9,10) en vez de alfabética (1,10,2,…).
  items = items.slice().sort((a, b) =>
    (a.codigo || a.sku || "").localeCompare((b.codigo || b.sku || ""), undefined, { numeric: true, sensitivity: "base" })
  );

  const etiquetas = items.map((it, idx) => {
    const codigo  = (it.codigo || it.sku || "").toUpperCase();
    const precio  = it.precio || 0;
    const marca   = it.marcaNombre || it.marca || "";
    return `
      <div class="label">
        <div class="top"><span>${marca.toUpperCase()}</span><span style="font-weight:bold">TOSCANA HOUSE</span></div>
        <div class="producto">${abreviarNombre((it.nombre||it.desc||"").toUpperCase())}</div>
        ${(()=>{const d=(it.descripcion||"").trim();const s=(it.subcat||"").trim();if(d)return`<div class="color-row">${d.toUpperCase()}</div>`;if(s)return`<div class="color-row">TALLA ${s.toUpperCase()}</div>`;return"";})()}
        <div class="barcode-wrap"><svg id="bc-${idx}"></svg></div>
        <div class="bottom-row">
          <span class="codigo">${codigo}</span>
          <span class="precio">Bs ${precio}</span>
        </div>
      </div>`;
  }).join('');

  const barcodeScripts = items.map((it, idx) => {
    const codigo = (it.codigo || it.sku || "").toUpperCase();
    return `try{JsBarcode("#bc-${idx}","${codigo}",{format:"CODE128",width:1.56,height:38.4,displayValue:false,margin:0});}catch(e){}`;
  }).join('\n');

  win.document.write(`<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Etiquetas — ${items.length} items</title>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/jsbarcode/3.11.5/JsBarcode.all.min.js"><\/script>
  <style>
    @page { size: 50mm 25mm; margin: 0; }
    * { box-sizing:border-box; margin:0; padding:0; }
    body { font-family:'Courier New',monospace; background:#fff; }
    .controls { padding:16px; background:#f5f3ee; display:flex; gap:12px; align-items:center;
      border-bottom:1px solid #e2ded8; }
    .btn-print { background:#1a1714; color:#fff; border:none; padding:10px 24px;
      border-radius:8px; font-size:14px; font-weight:700; cursor:pointer; }
    .btn-print:hover { background:#333; }
    .info { font-family:sans-serif; font-size:13px; color:#57534e; }
    .print-note { font-family:sans-serif; font-size:13px; color:#8a5a00; background:#fff7e6;
      border:1px solid #ffe0a3; border-radius:8px; padding:10px 16px; margin:0 16px 16px; line-height:1.5; }
    .labels-grid { display:flex; flex-direction:column; gap:4mm; padding:8mm; }
    .label { width:50mm; height:25mm; border:1px dashed #ccc; padding:1mm 2mm; box-sizing:border-box;
      overflow:hidden; background:#fff; display:flex; flex-direction:column; align-items:center; justify-content:center; }
    .top { display:flex; justify-content:space-between; align-items:center; width:100%;
      font-size:8.64px; letter-spacing:0.5px; text-transform:uppercase; color:#333; }
    .producto { font-size:7.5px; font-weight:bold; text-align:center; width:100%;
      text-transform:uppercase; line-height:1.15; margin:0.2mm 0;
      display:-webkit-box; -webkit-box-orient:vertical; -webkit-line-clamp:3;
      overflow:hidden; text-overflow:ellipsis; }
    .barcode-wrap { width:100%; display:flex; justify-content:center; }
    .barcode-wrap svg { width:45mm!important; height:8.5mm!important; }
    .color-row { font-size:6.5px; color:#555; text-transform:uppercase; letter-spacing:0.5px;
      text-align:center; width:100%; margin:0.1mm 0; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
    .bottom-row { display:flex; justify-content:space-between; align-items:center; width:100%;
      margin-top:0.1mm; }
    .codigo { font-size:8px; color:#333; font-family:monospace; }
    .precio { font-size:12px; font-weight:900; }
    @media print {
      .controls { display:none!important; }
      .print-note { display:none!important; }
      body { padding:0; }
      .labels-grid { gap:0; padding:0; }
      .label { border:none; page-break-after:always; }
      .label:last-child { page-break-after:auto; }
    }
  </style>
</head>
<body>
  <div class="controls">
    <button class="btn-print" onclick="window.print()">🖨 Imprimir ${items.length} etiqueta${items.length!==1?'s':''}</button>
    <span class="info">${items.length} etiqueta${items.length!==1?'s':''} generadas · 50x25mm</span>
  </div>
  <div class="print-note">
    ⚠️ Para que la etiqueta salga correcta: en la ventana de impresión, hacé clic en
    <strong>"Más ajustes"</strong> y luego en <strong>"Imprimir usando el cuadro de diálogo del sistema"</strong>
    (ahí queda el preajuste "TOSCANA" con tamaño y orientación correctos).
  </div>
  <div class="labels-grid">${etiquetas}</div>
  <script>
    window.onload = function(){
      ${barcodeScripts}
      setTimeout(()=>{ if(confirm('¿Imprimir ahora?')) window.print(); }, 800);
    };
  <\/script>
</body>
</html>`);
  win.document.close();
}

