// ── Helpers pago ──────────────────────────────────────────
function labelPago(mp){
  if(!mp) return "—";
  if(mp==="giftcard") return "Gift Card";
  if(mp.startsWith("mixto|")){
    if(mp.includes("giftcard")) return "Gift Card + Otro";
    return "Mixto";
  }
  return PAGOS.find(p=>p.id===mp)?.label||mp;
}
function colorPago(mp){
  if(!mp) return "#4A9B6F";
  if(mp==="giftcard") return "#7C3AED";
  if(mp.startsWith("mixto|")){
    if(mp.includes("giftcard")) return "#7C3AED";
    return "#6C5CE7";
  }
  return PAGOS.find(p=>p.id===mp)?.color||"#4A9B6F";
}
function iconPago(mp){
  if(!mp) return "";
  if(mp==="giftcard") return "🎁";
  if(mp.startsWith("mixto|")){
    if(mp.includes("giftcard")) return "🎁";
    return "🔀";
  }
  return PAGOS.find(p=>p.id===mp)?.icon||"";
}

// ── parsePago: desglosa cualquier metodoPago a montos reales por método ───────
// Mixto NO es método de pago — es una herramienta que distribuye el total
// entre efectivo / qr / tarjeta / giftcard. Esta función siempre devuelve
// los montos reales, sin importar si la venta fue mixta o no.
function parsePago(metodoPago, total){
  const res={efectivo:0,qr:0,tarjeta:0,giftcard:0};
  if(!metodoPago) return res;
  if(metodoPago.startsWith("mixto|")){
    metodoPago.split("|").slice(1).forEach(p=>{
      const [k,v]=p.split(":");
      if(k in res) res[k]=parseFloat(v)||0;
    });
    return res;
  }
  if(metodoPago in res) res[metodoPago]=total;
  else res.efectivo=total; // fallback
  return res;
}
// Suma parsePago sobre un array de ventas → {efectivo, qr, tarjeta, giftcard}
function sumPagos(ventas){
  return ventas.reduce((acc,v)=>{
    const p=parsePago(v.metodoPago,v.total);
    acc.efectivo+=p.efectivo; acc.qr+=p.qr;
    acc.tarjeta+=p.tarjeta;  acc.giftcard+=p.giftcard;
    return acc;
  },{efectivo:0,qr:0,tarjeta:0,giftcard:0});
}

// ── PagoDisplay: muestra el pago con desglose real para pagos mixtos ─────────
// Para pagos simples → un Chip. Para mixto → un Chip por método con su monto.
// prop inline=true → texto compacto "💵 Bs 80 · 📱 Bs 70" (para cards pequeñas)
const _PAGO_ICON  = {efectivo:"💵",qr:"📱",tarjeta:"💳",giftcard:"🎁"};
const _PAGO_COL   = {efectivo:C.green,qr:C.blue,tarjeta:C.amber,giftcard:"#7C3AED"};
const _PAGO_LBL   = {efectivo:"Efectivo",qr:"QR",tarjeta:"Tarjeta",giftcard:"GC"};
function PagoDisplay({mp, total, small, inline}){
  if(!mp) return null;
  if(mp.startsWith("mixto|")){
    const partes = mp.split("|").slice(1)
      .map(p=>{const[k,v]=p.split(":");return{k,amt:parseFloat(v)||0};})
      .filter(x=>x.amt>0);
    if(inline){
      return <>{partes.map((x,i)=>(
        <React.Fragment key={x.k}>
          {i>0&&<span style={{opacity:.4}}> · </span>}
          <span>{_PAGO_ICON[x.k]||"💱"} {$(x.amt)}</span>
        </React.Fragment>
      ))}</>;
    }
    return <>{partes.map(x=>(
      <Chip key={x.k} color={_PAGO_COL[x.k]||C.label3} small={small}>
        {_PAGO_ICON[x.k]||"💱"} {_PAGO_LBL[x.k]||x.k}: {$(x.amt)}
      </Chip>
    ))}</>;
  }
  return <Chip color={colorPago(mp)} small={small}>{iconPago(mp)} {labelPago(mp)}</Chip>;
}

// ── getMarcaImg: imagen efectiva de una marca ────────────────────────────────
// Prioridad: logo personalizado → seed por id → seed por nombre → imagen guardada
function getMarcaImg(m){
  if(!m) return "";
  if(m.imagenPersonalizada && m.imagen) return m.imagen;
  // Buscar en seed por id (tolerante a string/number) o por nombre como fallback
  const seed = MARCAS_SEED.find(s=>String(s.id)===String(m.id))
            || MARCAS_SEED.find(s=>s.nombre===m.nombre);
  return seed?.imagen || m.imagen || "";
}

// ── MarcaIcon: muestra imagen de logo o emoji como fallback ──────────────────
// Usar en cualquier lugar del UI donde aparezca el ícono de una marca.
function MarcaIcon({marca, size=20, radius=8, style={}}){
  if(!marca) return null;
  const img = getMarcaImg(marca);
  if(img){
    return <img src={img} alt={marca.nombre||""}
      style={{width:size,height:size,borderRadius:radius,
        objectFit:"cover",flexShrink:0,display:"inline-block",...style}}/>;
  }
  return <span style={{fontSize:size*0.85,lineHeight:1,flexShrink:0,
    display:"inline-block",...style}}>{marca.emoji||"◆"}</span>;
}

// ── Helpers ───────────────────────────────────────────────
const $    = n => "Bs " + new Intl.NumberFormat("es-BO",{minimumFractionDigits:0,maximumFractionDigits:2}).format(n||0);
const $1   = n => "Bs " + new Intl.NumberFormat("es-BO",{minimumFractionDigits:1,maximumFractionDigits:1}).format(n||0);
const hoy  = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`; };
const hora = () => new Date().toLocaleTimeString("es-BO",{hour:"2-digit",minute:"2-digit"});
// Convierte fecha ("2026-07-02") + hora ("06:18 p. m." / "18:18" / "—") a un
// número ordenable. La hora se guarda en formato 12h con a.m./p.m., por lo que
// compararla como texto ordena mal ("12:26 p.m." > "06:18 p.m.").
const tsVenta = v => {
  const [Y=0,M=1,D=1] = String(v.fecha||"").split("-").map(Number);
  const s  = String(v.hora||"").toLowerCase();
  const hm = s.match(/(\d{1,2}):(\d{2})/);
  let h = 0, min = 0;
  if(hm){
    h = +hm[1]; min = +hm[2];
    if(/p\.?\s*m/.test(s) && h < 12) h += 12;  // 06:18 p.m. → 18:18
    if(/a\.?\s*m/.test(s) && h === 12) h = 0;  // 12:05 a.m. → 00:05
  } else {
    // Ventas antiguas: sin hora, solo turno → posición representativa del día
    if(s.includes("mañana")||s.includes("manana")) h = 9;   // bloque mañana
    else if(s.includes("tarde"))                   h = 15;  // bloque tarde
    else if(s.includes("noche"))                   h = 20;  // bloque noche
  }
  return (((Y*12+M)*31+D)*24+h)*60 + min;
};
const mkKey= (m,a) => `${a}-${String(m+1).padStart(2,"0")}`;
const genCod=(mid,nombre,idx)=>{
  const m=MARCAS.find(x=>x.id===mid);
  const p=(m?.nombre||"TOS").replace(/[^a-zA-Z]/g,"").toUpperCase().slice(0,3);
  const s=(nombre||"ITEM").replace(/[^a-zA-Z0-9]/g,"").toUpperCase().slice(0,4);
  return `${p}-${s}-${String(idx).padStart(4,"0")}`;
};

// ════════════════════════════════════════════════════════════
// EXCEL ENGINE — SheetJS (xlsx) generador de reportes
// Genera .xlsx real con múltiples pestañas, estilos y fórmulas
// ════════════════════════════════════════════════════════════

// Carga xlsx-js-style (fork de SheetJS con soporte de estilos de celda)
// Drop-in replacement: misma API + propiedad .s en celdas para colores/bordes
let _XLSXPromise = null;
function loadXLSX() {
  if (_XLSXPromise) return _XLSXPromise;
  _XLSXPromise = new Promise((resolve, reject) => {
    if (window.XLSX) { resolve(window.XLSX); return; }
    const s = document.createElement("script");
    s.src = "https://cdn.jsdelivr.net/npm/xlsx-js-style@1.2.0/dist/xlsx.bundle.js";
    let settled = false;
    const done = (fn,arg)=>{ if(!settled){ settled=true; fn(arg); } };
    s.onload  = () => done(resolve, window.XLSX);
    s.onerror = () => done(reject, new Error("No se pudo cargar xlsx-js-style"));
    // Si el CDN tarda más de 12s (red lenta/bloqueada) caemos a la lib
    // empaquetada en vez de quedar colgados para siempre. La empaquetada
    // no tiene estilos de celda pero sí lee/escribe datos correctamente.
    setTimeout(()=>{
      if(window.__XLSXBundled) done(resolve, window.__XLSXBundled);
      else done(reject, new Error("Timeout cargando xlsx-js-style"));
    }, 12000);
    document.head.appendChild(s);
  }).catch(e => { _XLSXPromise = null; throw e; }); // permite reintentar si falló
  return _XLSXPromise;
}

// Para LEER/escribir archivos sin estilos de celda: usa la librería xlsx
// EMPAQUETADA en el bundle (no depende de ningún CDN → instantáneo y
// funciona offline). Es lo que evita que el import se quede en "Leyendo...".
async function getXLSXRead() {
  if (typeof window !== "undefined" && window.__XLSXBundled) return window.__XLSXBundled;
  return await loadXLSX(); // respaldo si por algún motivo no se empaquetó
}

// Helper: descargar blob como archivo
function descargarArchivo(blob, nombre) {
  const url = URL.createObjectURL(blob);
  const a   = document.createElement("a");
  a.href = url; a.download = nombre; a.click();
  URL.revokeObjectURL(url);
}

// ── File System Access API — carpetas organizadas por marca ──────────────
// Guarda/lee el handle de la carpeta base en IndexedDB (por dispositivo).
function _fsaIdb(mode, value){
  return new Promise(resolve=>{
    const req=indexedDB.open("th_fsa",1);
    req.onupgradeneeded=e=>e.target.result.createObjectStore("h");
    req.onsuccess=e=>{
      const db=e.target.result;
      const tx=db.transaction("h",mode==="get"?"readonly":"readwrite");
      const st=tx.objectStore("h");
      const r=mode==="get"?st.get("base"):st.put(value,"base");
      r.onsuccess=()=>resolve(r.result||null);
      r.onerror=()=>resolve(null);
    };
    req.onerror=()=>resolve(null);
  });
}
async function fsaGetBase(){
  const h=await _fsaIdb("get");
  if(!h) return null;
  try{
    const perm=await h.queryPermission({mode:"readwrite"});
    if(perm==="granted") return h;
    const req=await h.requestPermission({mode:"readwrite"});
    return req==="granted"?h:null;
  }catch{return null;}
}
async function fsaSetBase(){
  if(!("showDirectoryPicker" in window)) return null;
  try{
    const h=await window.showDirectoryPicker({mode:"readwrite",
      startIn:"downloads", id:"th-downloads"});
    await _fsaIdb("set",h);
    return h;
  }catch{return null;}
}
async function fsaHasBase(){
  const h=await _fsaIdb("get"); return !!h;
}

// Descarga un archivo a <carpetaBase>/<marcaCarpeta>/<nombre>
// Si FSA no disponible o no configurado → download normal.
async function descargarOrganizado(blob, nombre, marcaCarpeta, subcarpeta=null){
  const base=await fsaGetBase();
  if(base && marcaCarpeta){
    try{
      const carpeta=(marcaCarpeta||"General").replace(/[\/\\:*?"<>|]/g,"").trim()||"General";
      let dir=await base.getDirectoryHandle(carpeta,{create:true});
      if(subcarpeta){
        const sub=subcarpeta.replace(/[\/\\:*?"<>|]/g,"").trim();
        if(sub) dir=await dir.getDirectoryHandle(sub,{create:true});
      }
      const fh=await dir.getFileHandle(nombre,{create:true});
      const wr=await fh.createWritable();
      await wr.write(blob);
      await wr.close();
      return;
    }catch(e){ /* fallback */ }
  }
  descargarArchivo(blob,nombre);
}

