  const subtotalBruto=venta.items.reduce((s,i)=>s+i.precioUnit*i.cantidad,0);
  const displayTotal=getDisplayTotal(venta);
  const manualDescPct=getManualDescPct(venta);
  const descAdicional=subtotalBruto-displayTotal;
